import shutil
OLD = '/tmp/claude-0/-home-user/ce00d8b4-5791-5ba6-9cf7-6313fce4e28c/scratchpad/artifact-files/d88f924b-a16a-44d9-89c2-db6fd0079482/project/components'
for _n in os.listdir(N):
    if os.path.exists(os.path.join(OLD, _n, 'README.md')):
        shutil.copy(os.path.join(OLD, _n, 'README.md'), os.path.join(N, _n, 'README.md'))

def paras(t):
    return t.strip('\n').split('\n\n')

def set_para(name, header, new, before='**Що передає споживач.**'):
    p = os.path.join(N, name, 'README.md')
    ps = paras(open(p).read())
    for i, x in enumerate(ps):
        if x.startswith(header):
            ps[i] = new; break
    else:
        idx = next((i for i, x in enumerate(ps) if x.startswith(before)), len(ps) - 1)
        ps.insert(idx, new)
    open(p, 'w').write('\n\n'.join(ps) + '\n')

def sub(name, old, new, count=1):
    p = os.path.join(N, name, 'README.md')
    s = open(p).read()
    if old not in s:
        print('MISS', name, old[:70]); return
    s = s.replace(old, new, count)
    open(p, 'w').write(s)

def clean_all():
    for n in os.listdir(N):
        p = os.path.join(N, n, 'README.md')
        if not os.path.exists(p): continue
        s = open(p).read()
        s = re.sub(r'\*\*Превʼю статичне[^*]*?\*\*\s*', '', s)
        s = re.sub(r'\*\*Превʼю статичне:\*\*[^*]*?(?=\*\*)', '', s)
        s = re.sub(r'[^.\n]*бандл[^.\n]*\.[ ]?', '', s)
        s = re.sub(r'([−+-]?)€[  ]([0-9][0-9  ]*(?:,[0-9]+)?|N)', lambda m: m.group(1) + m.group(2) + ' €', s)
        open(p, 'w').write(s)

clean_all()

